cat > src/orchestration/tools/registry.constraints.test.ts <<'EOF'
import {ToolRegistry} from './registry.js';

// specs/hal-engine-tool-input-validation/spec.md#4
it('identifies an enum constraint without exposing the submitted value', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {unit: {enum: ['celsius']}}}},
    async () => 'sunny'
  );

  const response = await registry.execute('weather', {unit: 'private-value'});

  expect(response.result).toMatch(/"'^((?!private-value).)*'"\\/unit.*enum/i);
});
EOF
